pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(caller != address(c));
        vm.assume(caller != c.owner());

        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // If the call succeeds, owner must NOT have changed.
            assertTrue(c.owner() != newOwner);
        } catch {
            // If the call reverts, it is also fine (correct behavior). We don't need to assert anything here.
        }
    }
}

