pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address sender) public {
        vm.assume(sender != address(0));
        vm.assume(newOwner != sender);
        // Set the owner to the sender so they can call transferOwnership
        vm.prank(address(this));
        c.transferOwnership(sender);
        // Now sender calls transferOwnership to change owner to newOwner
        vm.prank(sender);
        c.transferOwnership(newOwner);
        // The owner should be newOwner after the call
        assertTrue(c.owner() == newOwner);
    }
}

