pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. Restrict admissible domain: newOwner must not be the current owner (address(0) by default)
        vm.assume(newOwner != address(0));

        // 2. The setUp() deploys C with owner = address(0) initially (since no constructor).
        //    To call transferOwnership, msg.sender must be owner (address(0)).
        //    The only way to satisfy onlyOwner after deployment is to prank as address(0).
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        // 3. After the call, owner() must equal newOwner. The buggy version leaves owner at address(0),
        //    so this assertion fails for any newOwner != address(0).
        assertTrue(c.owner() == newOwner);
    }
}

